var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# Run the bats suite under kcov and leave a merged report in coverage/."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# kcov is applied per invocation from the test helper rather than wrapped around bats: running kcov over"},
{"lineNum":"    6","line":"# bats collects nothing, because bats executes the code under test in grandchild processes (kcov issue"},
{"lineNum":"    7","line":"# #462). test/test_helper.bash notices COVERAGE_DIR and traces each invocation, and kcov accumulates"},
{"lineNum":"    8","line":"# into one output directory, writing a merged report beside one report per traced invocation. Only the"},
{"lineNum":"    9","line":"# merged report is published; the per-invocation ones each list every file while crediting a single"},
{"lineNum":"   10","line":"# run\'s hits, so they read as wrong."},
{"lineNum":"   11","line":"#"},
{"lineNum":"   12","line":"# Two kcov requirements are easy to get wrong: the target must be the *script*, never `bash script`,"},
{"lineNum":"   13","line":"# which instruments the bash binary instead; and the default PS4 collection method must be used, since"},
{"lineNum":"   14","line":"# --bash-method=DEBUG measures nothing here."},
{"lineNum":"   15","line":"#"},
{"lineNum":"   16","line":"# Function-level tests need a harness. `bash -c \'source …\'` sets $0 correctly but cannot be traced —"},
{"lineNum":"   17","line":"# kcov\'s prologue reads BASH_SOURCE, unset inside a -c string, so a script under `set -o nounset` dies"},
{"lineNum":"   18","line":"# before its function runs. A harness that kcov executes directly works, provided it sits beside the"},
{"lineNum":"   19","line":"# script, so the library path the script derives from $(dirname \"$0\") still resolves. This writes one"},
{"lineNum":"   20","line":"# into each directory holding a script, and removes them on exit."},
{"lineNum":"   21","line":"#"},
{"lineNum":"   22","line":"# kcov is not packaged for Ubuntu 24.04 (its Debian package was dropped over an FTBFS with GCC 15), so"},
{"lineNum":"   23","line":"# CI uses the upstream image. A locally installed kcov is preferred because it avoids the container"},
{"lineNum":"   24","line":"# round-trip; both produce identical figures. What runs inside the container is"},
{"lineNum":"   25","line":"# bin/coverage/in-container.sh, invoked through the mount."},
{"lineNum":"   26","line":"#"},
{"lineNum":"   27","line":"# Both files are measured like anything else under bin/. kcov reports only what it observes running, so"},
{"lineNum":"   28","line":"# they appear because test/bin/run-coverage.bats and test/bin/in-container.bats drive them — through the"},
{"lineNum":"   29","line":"# seams below, never the real kcov, bats or docker."},
{"lineNum":"   30","line":"#"},
{"lineNum":"   31","line":"# Usage: bin/coverage/run-coverage.sh"},
{"lineNum":"   32","line":"#   JUNIT_DIR=junit          also write bats\'s JUnit report there, for Codecov\'s test analytics"},
{"lineNum":"   33","line":"#   KCOV_FORCE_DOCKER=1      exercise the container path even with a local toolchain"},
{"lineNum":"   34","line":""},
{"lineNum":"   35","line":"set -o errexit","class":"lineCov","hits":"1","order":"4953",},
{"lineNum":"   36","line":"set -o nounset","class":"lineCov","hits":"1","order":"4958",},
{"lineNum":"   37","line":"set -o pipefail","class":"lineCov","hits":"1","order":"4963",},
{"lineNum":"   38","line":""},
{"lineNum":"   39","line":"SCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd -P)\"","class":"lineCov","hits":"1","order":"4966",},
{"lineNum":"   40","line":"readonly SCRIPT_DIR","class":"lineCov","hits":"1","order":"4970",},
{"lineNum":"   41","line":"# shellcheck source=../_lib/paths.sh"},
{"lineNum":"   42","line":"source \"${SCRIPT_DIR}/../_lib/paths.sh\"","class":"lineCov","hits":"1","order":"4973",},
{"lineNum":"   43","line":"readonly ROOT=\"${REPO_ROOT}\"","class":"lineCov","hits":"1","order":"4949",},
{"lineNum":"   44","line":""},
{"lineNum":"   45","line":"# Pinned by digest so the reported percentage cannot drift when the tag moves. Image: kcov/kcov"},
{"lineNum":"   46","line":"# v44-pre-test3; update deliberately, then re-check the gate in coverage.toml."},
{"lineNum":"   47","line":"KCOV_IMAGE=${KCOV_IMAGE:-kcov/kcov@sha256:481289ae32e55e5b733019515acd10948a4f76dfed381765577db909664fc603}","class":"lineCov","hits":"1","order":"4941",},
{"lineNum":"   48","line":""},
{"lineNum":"   49","line":"# The packaging scripts need mikefarah\'s yq, pinned to the version the workflows install so a figure"},
{"lineNum":"   50","line":"# measured here matches one measured there."},
{"lineNum":"   51","line":"YQ_VERSION=${YQ_VERSION:-v4.52.4}","class":"lineCov","hits":"1","order":"4978",},
{"lineNum":"   52","line":"export YQ_VERSION","class":"lineCov","hits":"1","order":"4968",},
{"lineNum":"   53","line":""},
{"lineNum":"   54","line":"# Debian\'s bats is 1.8, which predates BATS_TEST_TIMEOUT (added in 1.9). A suite that bounds a test to turn"},
{"lineNum":"   55","line":"# a runaway loop into a failure would silently have no bound there, so bats is installed from source at the"},
{"lineNum":"   56","line":"# version a local run and the macOS job use — all three then behave the same."},
{"lineNum":"   57","line":"#"},
{"lineNum":"   58","line":"# Normalised to a leading v, which the release tags carry, because bats exports BATS_VERSION itself: run"},
{"lineNum":"   59","line":"# from inside a suite — as this script\'s own tests do — the value is whatever the outer bats is, without"},
{"lineNum":"   60","line":"# the prefix, and the archive URL built from it is a 404 rather than an error that says so."},
{"lineNum":"   61","line":"BATS_VERSION=${BATS_VERSION:-v1.14.0}","class":"lineCov","hits":"1","order":"4955",},
{"lineNum":"   62","line":"BATS_VERSION=\"v${BATS_VERSION#v}\"","class":"lineCov","hits":"1","order":"4960",},
{"lineNum":"   63","line":"export BATS_VERSION","class":"lineCov","hits":"1","order":"4964",},
{"lineNum":"   64","line":""},
{"lineNum":"   65","line":"COVERAGE_HARNESS_NAME=\"_coverage-harness\"","class":"lineCov","hits":"1","order":"4956",},
{"lineNum":"   66","line":"export COVERAGE_HARNESS_NAME","class":"lineCov","hits":"1","order":"4962",},
{"lineNum":"   67","line":""},
{"lineNum":"   68","line":"# The three tools this decides between, named through the environment so a test can hand it doubles. They"},
{"lineNum":"   69","line":"# cannot be stubbed on PATH under the names they really have: a `kcov` or `bats` earlier on PATH would be"},
{"lineNum":"   70","line":"# picked up by the coverage harness tracing the test, and a `docker` would be handed to"},
{"lineNum":"   71","line":"# ufw-docker-expose\'s suite, which runs the real CLI against pinned images."},
{"lineNum":"   72","line":": \"${KCOV_BIN:=kcov}\"","class":"lineCov","hits":"1","order":"4975",},
{"lineNum":"   73","line":": \"${BATS_BIN:=bats}\"","class":"lineCov","hits":"1","order":"4951",},
{"lineNum":"   74","line":": \"${DOCKER_BIN:=docker}\"","class":"lineCov","hits":"1","order":"4946",},
{"lineNum":"   75","line":"readonly KCOV_BIN BATS_BIN DOCKER_BIN","class":"lineCov","hits":"1","order":"4944",},
{"lineNum":"   76","line":""},
{"lineNum":"   77","line":"cd \"${ROOT}\"","class":"lineCov","hits":"1","order":"4942",},
{"lineNum":"   78","line":""},
{"lineNum":"   79","line":"#######################################"},
{"lineNum":"   80","line":"# Removes the sourcing harnesses the test helper wrote beside the scripts."},
{"lineNum":"   81","line":"# The helper creates them on demand — it also needs them beside tool copies in fixture trees — and this"},
{"lineNum":"   82","line":"# is what guarantees none survive the run."},
{"lineNum":"   83","line":"# Globals:"},
{"lineNum":"   84","line":"#   ROOT, COVERAGE_HARNESS_NAME"},
{"lineNum":"   85","line":"#######################################"},
{"lineNum":"   86","line":"remove_harnesses() {"},
{"lineNum":"   87","line":"  find \"${ROOT}/scripts\" \"${ROOT}/bin\" -name \"${COVERAGE_HARNESS_NAME}\" -delete 2>/dev/null || true","class":"lineCov","hits":"1","order":"4939",},
{"lineNum":"   88","line":"}"},
{"lineNum":"   89","line":""},
{"lineNum":"   90","line":"#######################################"},
{"lineNum":"   91","line":"# Reports whether a locally installed kcov runs the scripts under a bash new enough for them."},
{"lineNum":"   92","line":"# kcov\'s macOS build ignores the shebang and execs /bin/bash, which there is 3.2 — and eight of these"},
{"lineNum":"   93","line":"# scripts use case conversion, associative arrays, mapfile or namerefs, so they fail on it in ways that"},
{"lineNum":"   94","line":"# look like test failures rather than a toolchain problem. Probed rather than assumed from the platform,"},
{"lineNum":"   95","line":"# so a fixed kcov or an unusual box is judged on what it actually does."},
{"lineNum":"   96","line":"# Returns:"},
{"lineNum":"   97","line":"#   0 when kcov runs bash 4 or newer, 1 otherwise."},
{"lineNum":"   98","line":"#######################################"},
{"lineNum":"   99","line":"local_kcov_runs_modern_bash() {"},
{"lineNum":"  100","line":"  local probe_dir probe out","class":"lineCov","hits":"1","order":"4972",},
{"lineNum":"  101","line":"  probe_dir=\"$(mktemp -d)\"","class":"lineCov","hits":"1","order":"4974",},
{"lineNum":"  102","line":"  probe=\"${probe_dir}/probe.sh\"","class":"lineCov","hits":"1","order":"4948",},
{"lineNum":"  103","line":"  printf \'#!/usr/bin/env bash\\nprintf \"%%s\" \"${BASH_VERSINFO[0]}\"\\n\' > \"${probe}\"","class":"lineCov","hits":"1","order":"4945",},
{"lineNum":"  104","line":"  chmod +x \"${probe}\"","class":"lineCov","hits":"1","order":"4943",},
{"lineNum":"  105","line":"  out=\"$(${KCOV_BIN} --include-path=\"${probe}\" \"${probe_dir}/out\" \"${probe}\" 2>/dev/null || true)\"","class":"lineCov","hits":"1","order":"4977",},
{"lineNum":"  106","line":"  rm -rf \"${probe_dir}\"","class":"lineCov","hits":"1","order":"4940",},
{"lineNum":"  107","line":"  [[ \"${out}\" =~ ^[0-9]+$ ]] && (( out >= 4 ))","class":"lineCov","hits":"1","order":"4938",},
{"lineNum":"  108","line":"}"},
{"lineNum":"  109","line":""},
{"lineNum":"  110","line":"rm -rf coverage","class":"lineCov","hits":"1","order":"4979",},
{"lineNum":"  111","line":"trap remove_harnesses EXIT","class":"lineCov","hits":"1","order":"4969",},
{"lineNum":"  112","line":"remove_harnesses","class":"lineCov","hits":"1","order":"4980",},
{"lineNum":"  113","line":""},
{"lineNum":"  114","line":"# bats writes a JUnit report when asked, which is what Codecov\'s test analytics reads. Its flags take a"},
{"lineNum":"  115","line":"# directory, so JUNIT_DIR is passed through as one; without it nothing extra is written."},
{"lineNum":"  116","line":"bats_report=()"},
{"lineNum":"  117","line":"if [[ -n \"${JUNIT_DIR:-}\" ]]; then","class":"lineCov","hits":"1","order":"4981",},
{"lineNum":"  118","line":"  case \"${JUNIT_DIR}\" in","class":"lineCov","hits":"1","order":"4982",},
{"lineNum":"  119","line":"    /*) echo \"run-coverage: JUNIT_DIR must be repo-relative\" >&2; exit 2 ;;","class":"lineCov","hits":"1","order":"4983",},
{"lineNum":"  120","line":"  esac"},
{"lineNum":"  121","line":"  mkdir -p \"${JUNIT_DIR}\"","class":"lineCov","hits":"1","order":"4961",},
{"lineNum":"  122","line":"  bats_report=(--report-formatter junit --output \"${JUNIT_DIR}\")","class":"lineCov","hits":"1","order":"4965",},
{"lineNum":"  123","line":"fi"},
{"lineNum":"  124","line":""},
{"lineNum":"  125","line":"# Prefer the local toolchain when it is complete and usable. KCOV_FORCE_DOCKER exercises the container"},
{"lineNum":"  126","line":"# path without pruning PATH to hide kcov, which would also hide python3 and everything else Homebrew"},
{"lineNum":"  127","line":"# provides and make the run fail somewhere unrelated."},
{"lineNum":"  128","line":"use_local=false","class":"lineCov","hits":"1","order":"4984",},
{"lineNum":"  129","line":"if [[ -z \"${KCOV_FORCE_DOCKER:-}\" ]] && command -v \"${KCOV_BIN}\" &>/dev/null && command -v \"${BATS_BIN}\" &>/dev/null; then","class":"lineCov","hits":"1","order":"4985",},
{"lineNum":"  130","line":"  if local_kcov_runs_modern_bash; then","class":"lineCov","hits":"1","order":"4986",},
{"lineNum":"  131","line":"    use_local=true","class":"lineCov","hits":"1","order":"4976",},
{"lineNum":"  132","line":"  else"},
{"lineNum":"  133","line":"    echo \"The local kcov runs the scripts under bash 3.x, which most of them cannot use.\" >&2","class":"lineCov","hits":"1","order":"4947",},
{"lineNum":"  134","line":"  fi"},
{"lineNum":"  135","line":"fi"},
{"lineNum":"  136","line":""},
{"lineNum":"  137","line":"if [[ \"${use_local}\" == true ]]; then","class":"lineCov","hits":"1","order":"4987",},
{"lineNum":"  138","line":"  echo \"Running the suite under the locally installed kcov …\"","class":"lineCov","hits":"1","order":"4988",},
{"lineNum":"  139","line":"  COVERAGE_DIR=\"${ROOT}/coverage\" ${BATS_BIN} --recursive \"${bats_report[@]}\" test/","class":"lineCov","hits":"1","order":"4989",},
{"lineNum":"  140","line":"else"},
{"lineNum":"  141","line":"  if [[ -n \"${KCOV_FORCE_DOCKER:-}\" ]]; then","class":"lineCov","hits":"1","order":"4990",},
{"lineNum":"  142","line":"    echo \"KCOV_FORCE_DOCKER is set; running the suite in ${KCOV_IMAGE} …\"","class":"lineCov","hits":"1","order":"4991",},
{"lineNum":"  143","line":"  else"},
{"lineNum":"  144","line":"    echo \"Running the suite in ${KCOV_IMAGE} …\"","class":"lineCov","hits":"1","order":"4992",},
{"lineNum":"  145","line":"  fi"},
{"lineNum":"  146","line":"  # Assembled as an array rather than one command: every -e is a decision with a reason, and a run of"},
{"lineNum":"  147","line":"  # them wrapped across continuations hides the lines it spans from kcov as well as from a reader."},
{"lineNum":"  148","line":"  docker_args=(run --rm)","class":"lineCov","hits":"1","order":"4993",},
{"lineNum":"  149","line":"  docker_args+=(-v \"${ROOT}:/src\" -w /src)","class":"lineCov","hits":"1","order":"4994",},
{"lineNum":"  150","line":"  docker_args+=(-e \"JUNIT_DIR=${JUNIT_DIR:-}\")","class":"lineCov","hits":"1","order":"4995",},
{"lineNum":"  151","line":"  docker_args+=(-e \"COVERAGE_HARNESS_NAME=${COVERAGE_HARNESS_NAME}\")","class":"lineCov","hits":"1","order":"4996",},
{"lineNum":"  152","line":"  docker_args+=(-e \"YQ_VERSION=${YQ_VERSION}\")","class":"lineCov","hits":"1","order":"4997",},
{"lineNum":"  153","line":"  docker_args+=(-e \"BATS_VERSION=${BATS_VERSION}\")","class":"lineCov","hits":"1","order":"4954",},
{"lineNum":"  154","line":"  docker_args+=(--entrypoint bash \"${KCOV_IMAGE}\")","class":"lineCov","hits":"1","order":"4959",},
{"lineNum":"  155","line":"  # Invoked through the mount rather than passed as a -c string, so the provisioning is a file that"},
{"lineNum":"  156","line":"  # ShellCheck reads, a test can source, and a comment can be written in."},
{"lineNum":"  157","line":"  docker_args+=(/src/bin/coverage/in-container.sh)","class":"lineCov","hits":"1","order":"4967",},
{"lineNum":"  158","line":"  ${DOCKER_BIN} \"${docker_args[@]}\"","class":"lineCov","hits":"1","order":"4971",},
{"lineNum":"  159","line":"fi"},
{"lineNum":"  160","line":""},
{"lineNum":"  161","line":"if [[ ! -f coverage/kcov-merged/coverage.json ]]; then","class":"lineCov","hits":"1","order":"4950",},
{"lineNum":"  162","line":"  echo \"run-coverage: kcov produced no merged report in coverage/\" >&2","class":"lineCov","hits":"1","order":"4952",},
{"lineNum":"  163","line":"  exit 1","class":"lineCov","hits":"1","order":"4957",},
{"lineNum":"  164","line":"fi"},
{"lineNum":"  165","line":"echo \"Coverage in coverage/kcov-merged/\"","class":"lineCov","hits":"1","order":"4937",},
]};
